// Prints the demo access card (LOCAL demo only; credentials are regenerated by every seed run).
import { readFileSync, writeFileSync } from "node:fs";

const creds = JSON.parse(readFileSync(".secrets/seed-credentials.json", "utf8")) as {
  password: string;
  accounts: Record<string, string>;
  superadmin_totp_secret: string;
};
const a = creds.accounts;
const text = [
  "MSchool — локальное демо (синтетические данные)",
  "",
  "Адрес:          http://localhost:3000",
  `Пароль (все):   ${creds.password}`,
  "",
  `Сотрудник:      ${a.emp_a_junior1}`,
  `HR компании A:  ${a.hr_a}`,
  `HR компании B:  ${a.hr_b}`,
  `Суперадмин:     ${a.superadmin}`,
  "                код MFA: npm run demo:code",
  `                (или добавьте секрет ${creds.superadmin_totp_secret} в приложение-аутентификатор)`,
  "",
  "Письма-приглашения (локальный Mailpit): http://localhost:54324",
  "Сценарий показа: docs/demo-guide.md",
].join("\n");
writeFileSync(".secrets/demo-access.txt", `${text}\n`, { mode: 0o600 });
console.log(`\n${text}\n\n(сохранено в .secrets/demo-access.txt)`);
